import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';
import { vec3, uv, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  // Root group
  const root = new THREE.Group();
  root.position.set(
    config.position?.[0] ?? 0,
    config.position?.[1] ?? 0,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // ---------- GEAR MESHES ----------
  const glb = ctx.glbLoader(config.assets?.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb');
  const primaryGear = glb.scene.clone();
  primaryGear.name = 'primaryGear';
  primaryGear.scale.setScalar(1.6); // normalized to 1.6‑unit diameter
  root.add(primaryGear);

  const secondaryGear = primaryGear.clone();
  secondaryGear.name = 'secondaryGear';
  secondaryGear.scale.setScalar(0.9);
  secondaryGear.position.set(1.15, 0.35, -0.1);
  root.add(secondaryGear);

  // ---------- ROTATION ANIMATIONS ----------
  const primaryDuration = (2 * Math.PI) / 0.08; // seconds for full turn
  const secondaryDuration = (2 * Math.PI) / 0.142; // seconds for full turn (opposite)

  const primaryAnim = gsap.to(primaryGear.rotation, {
    z: '+=' + (2 * Math.PI),
    duration: primaryDuration,
    repeat: -1,
    ease: 'none',
  });

  const secondaryAnim = gsap.to(secondaryGear.rotation, {
    z: '-=' + (2 * Math.PI),
    duration: secondaryDuration,
    repeat: -1,
    ease: 'none',
  });

  // ---------- JEWEL PIVOT ----------
  const jewelGeom = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMat = new THREE.MeshPhysicalMaterial({
    color: 0xff2a38,
    transmission: 0.6,
    ior: 1.76,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 0,
    clearcoat: 0,
  });
  const jewel = new THREE.Mesh(jewelGeom, jewelMat);
  jewel.name = 'jewelPivot';
  root.add(jewel);

  // ---------- ARBOR SHAFTS ----------
  const shaftGeom = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new THREE.MeshPhysicalMaterial({
    color: 0x16161d,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    anisotropy: 0.7,
  });

  const primaryShaft = new THREE.Mesh(shaftGeom, shaftMat);
  primaryShaft.rotation.x = Math.PI / 2;
  primaryShaft.name = 'primaryShaft';
  root.add(primaryShaft);

  const secondaryShaft = new THREE.Mesh(shaftGeom, shaftMat);
  secondaryShaft.rotation.x = Math.PI / 2;
  secondaryShaft.position.copy(secondaryGear.position);
  secondaryShaft.name = 'secondaryShaft';
  root.add(secondaryShaft);

  // ---------- CONTACT SHADOW ----------
  const shadowGeom = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    opacity: 0.5,
    transparent: true,
    depthWrite: false,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);
  shadow.name = 'contactShadow';
  root.add(shadow);

  // ---------- BACKDROP WITH RADIAL GRADIENT ----------
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  // Gradient built with three/tsl nodes
  const gradientNode = mix(
    new THREE.Color('#0b0b10'),
    new THREE.Color('#16161d'),
    uv().y
  );
  const backdropMat = new THREE.MeshStandardNodeMaterial({
    color: gradientNode,
    side: THREE.DoubleSide,
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  backdrop.name = 'backdropPlane';
  root.add(backdrop);

  // ---------- TEXT ELEMENTS ----------
  const headlineOpts = {
    fontSize: 68,
    fontWeight: 600,
    fontFamily: 'Lora',
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
    atlas: 0,
    sourceRect: [0, 0, 512, 320],
  };
  const captionOpts = {
    fontSize: 18,
    fontWeight: 400,
    fontFamily: 'JetBrains Mono',
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
    atlas: 0,
    sourceRect: [0, 0, 512, 320],
  };

  const headline = textUtils.createTextMesh('The going train', headlineOpts);
  headline.position.set(0, -1.7, 0);
  headline.name = 'headlineText';
  root.add(headline);

  const caption = textUtils.createTextMesh('34 COMPONENTS / HAND-FINISHED', captionOpts);
  caption.position.set(0, -2.1, 0);
  caption.name = 'captionText';
  root.add(caption);

  // ---------- APPLY CINEMATIC PRIMITIVES ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params || {});
      }
    }
  }

  // ---------- USER DATA ----------
  root.userData.handlers = {};

  const timelines = [primaryAnim, secondaryAnim];

  root.userData.cleanup = () => {
    // Kill GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
    // Dispose custom geometries/materials
    jewelGeom.dispose();
    jewelMat.dispose();
    shaftGeom.dispose();
    shaftMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    backdropGeom.dispose();
    if (backdropMat.dispose) backdropMat.dispose();

    // Dispose GLB resources (traverse)
    primaryGear.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
    secondaryGear.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
  };

  return root;
}
